"""token_assembler: Convert raw Soniox tokens into subtitle blocks.

Extracted from SonioxAsyncService._render_tokens_json and _insert_split_tags.
These are pure functions with no I/O dependencies.
"""
from __future__ import annotations

import re
from typing import Any

# Max subtitle length per language; default for all others
_SUBTITLE_MAX_LENGTH: dict[str, int] = {"ja": 80}
_SUBTITLE_MAX_LENGTH_DEFAULT = 100


def insert_split_tags(text: str, start_ms: int | None, end_ms: int | None, max_length: int) -> str:
    """Insert <split:timing_ms> tags at natural break points when text exceeds max_length.

    Splits on comma/semicolon boundaries, keeping each chunk as long as possible
    while staying within max_length. Timing is proportional to character position.
    """
    if len(text) <= max_length:
        return text
    if start_ms is None or end_ms is None:
        return text

    total_len = len(text)
    total_duration = end_ms - start_ms

    # Split on comma/semicolon, keeping delimiter on the left side
    atoms = re.split(r"(?<=[,、，;；])", text)
    atoms = [a for a in atoms if a]

    result_parts: list[str] = []
    current_chunk = ""
    char_cursor = 0

    for atom in atoms:
        candidate = current_chunk + atom
        if len(candidate) <= max_length:
            current_chunk = candidate
        else:
            if current_chunk:
                result_parts.append(current_chunk)
                char_cursor += len(current_chunk)
                split_timing = int(start_ms + (char_cursor / total_len) * total_duration)
                result_parts.append(f"<split:{split_timing}>")
                current_chunk = atom.lstrip(" ")
            else:
                # Single atom already exceeds max; keep it as-is
                current_chunk = atom

    if current_chunk:
        result_parts.append(current_chunk)

    return "".join(result_parts)


def render_tokens_to_blocks(
    tokens: list[dict[str, Any]],
    insert_split_tag: bool = True,
    segment_offset_ms: int = 0,
) -> list[dict[str, Any]]:
    """Convert a flat list of Soniox tokens into grouped subtitle blocks.

    Groups consecutive tokens by (speaker, language), breaking at sentence endings.
    Applies split tags to blocks exceeding the per-language max length.

    Args:
        tokens: Raw token dicts from Soniox (text, speaker, language, start_ms, end_ms).
        insert_split_tag: Whether to insert <split:N> tags in long blocks.
        segment_offset_ms: Millisecond offset to add to all timestamps (for segment merging).

    Returns:
        List of block dicts: {speaker, language, start_ms, end_ms, text}.
    """
    output: list[dict[str, Any]] = []
    sentence_endings = {'.', '!', '?', '。', '！', '？'}

    current_speaker: str | None = None
    current_language: str | None = None
    current_start_ms: int | None = None
    current_end_ms: int | None = None
    text_parts: list[str] = []

    def _flush_block() -> None:
        nonlocal current_speaker, current_language, current_start_ms, current_end_ms, text_parts
        text_block = "".join(text_parts).strip()
        if text_block and current_start_ms is not None:
            start = current_start_ms + segment_offset_ms
            end = (current_end_ms or current_start_ms) + segment_offset_ms
            block_text = text_block
            if insert_split_tag:
                max_len = _SUBTITLE_MAX_LENGTH.get(current_language or "", _SUBTITLE_MAX_LENGTH_DEFAULT)
                block_text = insert_split_tags(block_text, start, end, max_len)
            output.append({
                "speaker": current_speaker,
                "language": current_language,
                "start_ms": start,
                "end_ms": end,
                "text": block_text,
            })
        current_start_ms = None
        current_end_ms = None
        text_parts = []

    for token in tokens:
        text = token.get("text", "")
        speaker = token.get("speaker")
        language = token.get("language")
        start_ms = token.get("start_ms")
        end_ms = token.get("end_ms")

        if current_start_ms is None:
            current_speaker = speaker
            current_language = language
            current_start_ms = start_ms

        is_sentence_end = bool(text and text.strip() and text.strip()[-1] in sentence_endings)
        speaker_or_lang_changed = (
            speaker is None or language is None
            or speaker != current_speaker or language != current_language
        )

        if speaker_or_lang_changed:
            _flush_block()
            current_speaker = speaker
            current_language = language
            current_start_ms = start_ms
            current_end_ms = end_ms
            text_parts = [text]
        else:
            current_end_ms = end_ms
            text_parts.append(text)
            if is_sentence_end:
                _flush_block()
                current_speaker = speaker
                current_language = language

    # Flush remaining tokens
    _flush_block()

    return output
